-- places/local-units
-- Local units of one district, for the optional local-unit select on the report form.
--
-- Parameters, with the example values used to render this file:
--   $1 = "00000000-0000-7000-8000-000000000027"
--
-- Generated by `pnpm db:queries` from lib/db/queries/places.ts. Do not edit by hand.

select "id", "name_en", "name_np", "type"
from "local_units"
where "local_units"."district_id" = $1
order by "local_units"."name_en" asc;
